import React from 'react';
import './BackgroundAnimation.css';

const BackgroundAnimation = () => {
  return (
    <div className="background-animation-container" style={{ pointerEvents: 'none' }}>
      <div className="bg-image img-1"></div>
      <div className="bg-image img-2"></div>
      <div className="bg-image img-3"></div>
      <div className="bg-overlay"></div>
    </div>
  );
};

export default BackgroundAnimation;
